-- Note: dedicated SQL pools do not support default parameter values; callers pass every parameter.
-- Stored procedures called by PL_Cab_Data_Ingestion / PL_SQL_Object_Test / PL_Validation.
IF OBJECT_ID('operation.usp_LogPipelineRun') IS NOT NULL DROP PROCEDURE operation.usp_LogPipelineRun;
GO
CREATE PROCEDURE operation.usp_LogPipelineRun
    @PipelineName  varchar(200),
    @PipelineRunId varchar(100),
    @ActivityName  varchar(200),
    @RunStatus     varchar(20),
    @RunMessage    varchar(4000)
AS
BEGIN
    INSERT INTO operation.PipelineRunLog (PipelineName, PipelineRunId, ActivityName, RunStatus, RunMessage, LoggedAtUtc)
    SELECT @PipelineName, @PipelineRunId, @ActivityName, @RunStatus, @RunMessage, GETUTCDATE();
END;
GO

IF OBJECT_ID('operation.usp_LoadStageCabTrips') IS NOT NULL DROP PROCEDURE operation.usp_LoadStageCabTrips;
GO
CREATE PROCEDURE operation.usp_LoadStageCabTrips
    @StorageAccount varchar(100),
    @Container      varchar(100)
AS
BEGIN
    -- Loads curated Parquet (written by JBD_Process_Cab_Data) into the stage tables using the workspace managed identity.
    -- COPY with IDENTITY = 'Managed Identity' needs the ADLS Gen2 (.dfs) endpoint; the .blob endpoint is rejected.
    DECLARE @root varchar(500) = 'https://' + @StorageAccount + '.dfs.core.windows.net/' + @Container + '/migration-test/nyccab/curated/';
    DECLARE @sql varchar(4000);

    TRUNCATE TABLE stage.NYCCabTrip_Green;
    TRUNCATE TABLE stage.NYCCabTrip_Yellow;
    TRUNCATE TABLE stage.TaxiZoneLookup;

    SET @sql = 'COPY INTO stage.NYCCabTrip_Green FROM ''' + @root + 'green/*.parquet'' WITH (FILE_TYPE = ''PARQUET'', CREDENTIAL = (IDENTITY = ''Managed Identity''))';
    EXEC (@sql);

    SET @sql = 'COPY INTO stage.NYCCabTrip_Yellow FROM ''' + @root + 'yellow/*.parquet'' WITH (FILE_TYPE = ''PARQUET'', CREDENTIAL = (IDENTITY = ''Managed Identity''))';
    EXEC (@sql);

    SET @sql = 'COPY INTO stage.TaxiZoneLookup FROM ''' + @root + 'taxi_zone_lookup/*.parquet'' WITH (FILE_TYPE = ''PARQUET'', CREDENTIAL = (IDENTITY = ''Managed Identity''))';
    EXEC (@sql);
END;
GO

IF OBJECT_ID('operation.usp_LoadDimLocation') IS NOT NULL DROP PROCEDURE operation.usp_LoadDimLocation;
GO
CREATE PROCEDURE operation.usp_LoadDimLocation
AS
BEGIN
    -- Full reload from the zone snapshot. LocationKey is set to the TLC LocationID (IDENTITY_INSERT) because
    -- dedicated-pool IDENTITY values are not sequential/deterministic, which would break row-level
    -- Synapse vs Fabric comparisons after migration.
    TRUNCATE TABLE dw.DimLocation;

    SET IDENTITY_INSERT dw.DimLocation ON;

    INSERT INTO dw.DimLocation (LocationKey, LocationID, Borough, Zone, service_zone)
    SELECT DISTINCT TRY_CAST(z.LocationID AS int), TRY_CAST(z.LocationID AS smallint),
           LEFT(z.Borough, 50), LEFT(z.Zone, 50), LEFT(z.service_zone, 50)
    FROM stage.TaxiZoneLookup z
    WHERE TRY_CAST(z.LocationID AS smallint) IS NOT NULL;

    SET IDENTITY_INSERT dw.DimLocation OFF;
END;
GO

IF OBJECT_ID('operation.usp_LoadFactCabTrip') IS NOT NULL DROP PROCEDURE operation.usp_LoadFactCabTrip;
GO
CREATE PROCEDURE operation.usp_LoadFactCabTrip
AS
BEGIN
    TRUNCATE TABLE dw.FactCabTrip;

    INSERT INTO dw.FactCabTrip
    (
        CabTripKey, VendorKey, CabTypeKey, LpepPickupDatetime, LpepDropoffDatetime, StoreAndFwdFlag,
        RateKey, PULocationKey, DOLocationKey, TripTypeKey, PaymentTypeKey, PassengerCount, TripDistance,
        FareAmount, Extra, MtaTax, TipAmount, TollsAmount, EhailFee, ImprovementSurcharge, TotalAmount
    )
    SELECT
        -- Deterministic surrogate key: stage rows are de-duplicated, so ordering by every column gives the
        -- same CabTripKey on every run and on every platform (needed for row-level migration comparison).
        ROW_NUMBER() OVER (ORDER BY t.CabType, t.Pickup, t.Dropoff, TRY_CAST(t.PULocationID AS int),
                                    TRY_CAST(t.DOLocationID AS int), t.VendorID, t.RatecodeID, t.payment_type,
                                    t.trip_type, t.passenger_count, t.store_and_fwd_flag,
                                    TRY_CAST(t.trip_distance AS decimal(10,2)), TRY_CAST(t.fare_amount AS decimal(10,2)),
                                    TRY_CAST(t.extra AS decimal(10,2)), TRY_CAST(t.tip_amount AS decimal(10,2)),
                                    TRY_CAST(t.tolls_amount AS decimal(10,2)), TRY_CAST(t.total_amount AS decimal(10,2))),
        v.VendorKey, c.CabTypeKey, t.Pickup, t.Dropoff, LEFT(t.store_and_fwd_flag, 1),
        r.RateKey, pu.LocationKey, dl.LocationKey,
        -- Yellow cabs have no trip type: use the 'Not applicable' member (key 0) instead of NULL so INNER JOINs keep them.
        CASE WHEN t.CabType = 'Yellow' THEN 0 ELSE tt.TripTypeKey END, p.PaymentTypeKey,
        TRY_CAST(t.passenger_count AS tinyint), TRY_CAST(t.trip_distance AS decimal(10,2)),
        TRY_CAST(t.fare_amount AS decimal(10,2)), TRY_CAST(t.extra AS decimal(10,2)),
        TRY_CAST(t.mta_tax AS decimal(10,2)), TRY_CAST(t.tip_amount AS decimal(10,2)),
        TRY_CAST(t.tolls_amount AS decimal(10,2)), TRY_CAST(t.ehail_fee AS decimal(10,2)),
        TRY_CAST(t.improvement_surcharge AS decimal(10,2)), TRY_CAST(t.total_amount AS decimal(10,2))
    FROM
    (
        SELECT 'Green' AS CabType, TRY_CAST(lpep_pickup_datetime AS datetime) AS Pickup,
               TRY_CAST(lpep_dropoff_datetime AS datetime) AS Dropoff, VendorID, store_and_fwd_flag, RatecodeID,
               PULocationID, DOLocationID, passenger_count, trip_distance, fare_amount, extra, mta_tax, tip_amount,
               tolls_amount, ehail_fee, improvement_surcharge, total_amount, payment_type, trip_type
        FROM stage.NYCCabTrip_Green
        UNION ALL
        SELECT 'Yellow', TRY_CAST(lpep_pickup_datetime AS datetime), TRY_CAST(lpep_dropoff_datetime AS datetime),
               VendorID, store_and_fwd_flag, RatecodeID, PULocationID, DOLocationID, passenger_count, trip_distance,
               fare_amount, extra, mta_tax, tip_amount, tolls_amount, NULL, improvement_surcharge, total_amount,
               payment_type, NULL
        FROM stage.NYCCabTrip_Yellow
    ) t
    LEFT JOIN dw.DimCabType     c  ON c.CabTypeDescription = t.CabType
    LEFT JOIN dw.DimVendor      v  ON v.VendorID       = TRY_CAST(t.VendorID AS smallint)
    LEFT JOIN dw.DimRate        r  ON r.RateID         = TRY_CAST(t.RatecodeID AS smallint)
    LEFT JOIN dw.DimLocation    pu ON pu.LocationID    = TRY_CAST(t.PULocationID AS smallint)
    LEFT JOIN dw.DimLocation    dl ON dl.LocationID    = TRY_CAST(t.DOLocationID AS smallint)
    LEFT JOIN dw.DimTripType    tt ON tt.TripTypeID    = TRY_CAST(t.trip_type AS smallint)
    LEFT JOIN dw.DimPaymentType p  ON p.PaymentTypeID  = TRY_CAST(t.payment_type AS smallint);
END;
GO

IF OBJECT_ID('operation.usp_ValidateFactLoad') IS NOT NULL DROP PROCEDURE operation.usp_ValidateFactLoad;
GO
CREATE PROCEDURE operation.usp_ValidateFactLoad
    @PipelineName  varchar(200),
    @PipelineRunId varchar(100)
AS
BEGIN
    -- Fails (THROW) when the fact table does not reconcile with stage, so the pipeline activity fails.
    DECLARE @green bigint, @yellow bigint, @fact bigint, @orphans bigint, @dq bigint, @dupkeys bigint, @msg varchar(4000);

    SELECT @green  = COUNT_BIG(*) FROM stage.NYCCabTrip_Green;
    SELECT @yellow = COUNT_BIG(*) FROM stage.NYCCabTrip_Yellow;
    SELECT @fact   = COUNT_BIG(*) FROM dw.FactCabTrip;
    SELECT @orphans = COUNT_BIG(*) FROM dw.FactCabTrip
    WHERE VendorKey IS NULL OR CabTypeKey IS NULL OR RateKey IS NULL OR PaymentTypeKey IS NULL OR TripTypeKey IS NULL
       OR PULocationKey IS NULL OR DOLocationKey IS NULL;
    -- Business-rule violations the cleaning step must have removed / the generator must never produce.
    SELECT @dq = COUNT_BIG(*) FROM dw.FactCabTrip
    WHERE LpepPickupDatetime IS NULL OR LpepDropoffDatetime < LpepPickupDatetime OR FareAmount < 0
       OR TotalAmount < FareAmount OR (PaymentTypeKey <> 1 AND TipAmount <> 0);
    SELECT @dupkeys = COUNT_BIG(*) - COUNT_BIG(DISTINCT CabTripKey) FROM dw.FactCabTrip;

    SET @msg = 'stage=' + CAST(@green + @yellow AS varchar(20)) + ' fact=' + CAST(@fact AS varchar(20))
             + ' unmatched_dim_keys=' + CAST(@orphans AS varchar(20)) + ' dq_violations=' + CAST(@dq AS varchar(20))
             + ' duplicate_keys=' + CAST(@dupkeys AS varchar(20));

    IF @fact = 0 OR @fact <> @green + @yellow OR @orphans > 0 OR @dq > 0 OR @dupkeys > 0
    BEGIN
        EXEC operation.usp_LogPipelineRun @PipelineName, @PipelineRunId, 'usp_ValidateFactLoad', 'Failed', @msg;
        SET @msg = 'Fact load validation failed: ' + @msg;
        THROW 50001, @msg, 1;
    END;

    EXEC operation.usp_LogPipelineRun @PipelineName, @PipelineRunId, 'usp_ValidateFactLoad', 'Succeeded', @msg;
END;
GO
